import json, os
from datetime import datetime, timedelta, timezone

LOOKBACK_MIN = int(os.environ.get('LOOKBACK_MIN') or 30)
MODE = (os.environ.get('INSPECT_MODE') or 'auto').strip().lower()

def load(name):
    raw = os.environ.get(name, '') or '{}'
    try:
        return json.loads(raw)
    except Exception:
        return {}

def parse(ts):
    if not ts:
        return None
    s = str(ts).replace('Z', '+00:00')
    try:
        d = datetime.fromisoformat(s)
        return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
    except Exception:
        return None

series = load('METRIC_JSON')
metric = os.environ.get('METRIC_NAME', 'metric')
# The spike threshold is the alarm's own. Baseline is what sits clearly
# below it - proportional, so this works for percentages and bytes alike
# rather than assuming a 0-100 scale.
try:
    SPIKE_AT = float(os.environ.get('SPIKE_THRESHOLD') or 70)
except ValueError:
    SPIKE_AT = 70.0
BASELINE_UNDER = SPIKE_AT * 0.7
ssm = load('SSM_JSON')
instance = os.environ.get('INSTANCE', '')

pts = sorted(series.get('Datapoints', []), key=lambda p: str(p.get('Timestamp', '')))
baseline = [p for p in pts if (p.get('Average') or 0) < BASELINE_UNDER]
spiked = [p for p in pts if (p.get('Average') or 0) >= SPIKE_AT]
base_avg = round(sum((p.get('Average') or 0) for p in baseline) / len(baseline), 1) if baseline else None
peak = round(max([(p.get('Maximum') or p.get('Average') or 0) for p in pts], default=0), 1)
spike_start = parse(spiked[0].get('Timestamp')) if spiked else None
spike_end = parse(spiked[-1].get('Timestamp')) if spiked else None

lower = (spike_start - timedelta(minutes=LOOKBACK_MIN)) if spike_start else None
upper = spike_end or None

cmds = []
for c in ssm.get('Commands', []):
    when = parse(c.get('RequestedDateTime'))
    if lower and upper and when and not (lower <= when <= upper):
        continue
    params = c.get('Parameters') or {}
    text = params.get('commands') or []
    if isinstance(text, list):
        text = ' ; '.join(str(t) for t in text)
    rel = 'unknown'
    if when and spike_start:
        rel = 'before_spike' if when <= spike_start else 'during_spike'
    cmds.append({
        'command_id': c.get('CommandId'),
        'requested_at': c.get('RequestedDateTime'),
        'relative_to_spike': rel,
        'document': c.get('DocumentName'),
        'status': c.get('Status'),
        'comment': c.get('Comment'),
        'command_text': text,
    })
cmds.sort(key=lambda c: str(c.get('requested_at') or ''))

likely = [c for c in cmds if c['relative_to_spike'] == 'before_spike']
if not spiked:
    verdict = 'no_spike_detected'
elif likely:
    verdict = 'operator_command_likely_cause'
elif cmds:
    verdict = 'commands_during_spike_only'
else:
    verdict = 'spike_without_ssm_activity'

if MODE == 'never':
    should_inspect = 'no'
elif MODE == 'always':
    should_inspect = 'yes'
else:
    should_inspect = 'no' if verdict == 'operator_command_likely_cause' else 'yes'

print(json.dumps({
    'instance_id': instance,
    'metric_name': metric,
    'spike_threshold': SPIKE_AT,
    'baseline_value': base_avg,
    'peak_value': peak,
    'spike_start': spike_start,
    'spike_end': spike_end,
    'spike_minutes': len(spiked),
    'lookback_minutes': LOOKBACK_MIN,
    'ssm_command_count': len(cmds),
    'likely_cause_count': len(likely),
    'ssm_commands': cmds,
    'verdict': verdict,
    'should_inspect': should_inspect,
}, default=str))

#!/bin/bash
set -o pipefail
ACTION="${ACTION:-triage}"
hr() { echo; echo "===== $1 ====="; }
case "$ACTION" in
  triage)
    hr "uptime / load"; uptime
    hr "top 10 by CPU"; ps -eo pid,ppid,user,pcpu,pmem,etime,lstart,cmd --sort=-pcpu 2>/dev/null | head -11
    hr "top 10 by memory"; ps -eo pid,ppid,user,pcpu,pmem,etime,cmd --sort=-pmem 2>/dev/null | head -11
    hr "memory"; free -m 2>/dev/null
    hr "disk"; df -hP 2>/dev/null
    hr "boot time"; who -b 2>/dev/null; uptime -s 2>/dev/null ;;
  top_cpu)    hr "top 20 by CPU"; ps -eo pid,ppid,user,pcpu,pmem,etime,lstart,cmd --sort=-pcpu 2>/dev/null | head -21 ;;
  top_memory) hr "top 20 by memory"; ps -eo pid,ppid,user,pcpu,pmem,etime,lstart,cmd --sort=-pmem 2>/dev/null | head -21 ;;
  disk_usage) hr "filesystems"; df -hP 2>/dev/null; hr "largest dirs under /var"; du -xh --max-depth=2 /var 2>/dev/null | sort -rh | head -20 ;;
  memory_usage) hr "free"; free -m 2>/dev/null; hr "meminfo"; head -20 /proc/meminfo 2>/dev/null ;;
  network_connections) hr "listening"; ss -tulpn 2>/dev/null | head -60; hr "established"; ss -tnp state established 2>/dev/null | head -60 ;;
  running_services) hr "running units"; systemctl list-units --type=service --state=running --no-pager 2>/dev/null | head -60 ;;
  failed_services) hr "failed units"; systemctl --failed --no-pager 2>/dev/null ;;
  recent_logins) hr "last logins"; last -a -n 40 2>/dev/null; hr "logged in now"; w 2>/dev/null ;;
  shell_history)
    hr "shell history (most recent 100 per user)"
    for f in /root/.bash_history /home/*/.bash_history; do
      [ -r "$f" ] || continue; echo "--- $f"; tail -100 "$f" 2>/dev/null
    done ;;
  cron_jobs)
    hr "system crontab"; cat /etc/crontab 2>/dev/null
    hr "cron.d"; ls -la /etc/cron.d 2>/dev/null
    hr "per-user crontabs"
    for u in $(cut -d: -f1 /etc/passwd 2>/dev/null); do
      out=$(crontab -l -u "$u" 2>/dev/null); [ -n "$out" ] && { echo "--- $u"; echo "$out"; }
    done
    hr "systemd timers"; systemctl list-timers --all --no-pager 2>/dev/null | head -30 ;;
  recent_syslog) hr "journal (warning+, last 200)"; journalctl -p warning -n 200 --no-pager 2>/dev/null ;;
  process_tree) hr "process tree"; ps -ejH -o pid,ppid,user,pcpu,etime,cmd 2>/dev/null | head -120 ;;
  boot_time) hr "boot"; who -b 2>/dev/null; uptime -s 2>/dev/null; uptime ;;
  package_changes)
    hr "recent package activity"
    if command -v rpm >/dev/null 2>&1; then rpm -qa --last 2>/dev/null | head -40; fi
    if command -v dpkg >/dev/null 2>&1; then grep -h ' install \| upgrade ' /var/log/dpkg.log 2>/dev/null | tail -40; fi ;;
  *) echo "ERROR: unknown host_action '$ACTION'"; exit 2 ;;
esac

